export const getDefaultParams = (method) => {
    const params = {};
    if (!CONTROLLER_CONFIGS[method]) return params;
    for (const [key, value] of Object.entries(CONTROLLER_CONFIGS[method].params)) {
        params[key] = value[0];
    }
    return params;
};

export const validateControllerConfigs = (configs = CONTROLLER_CONFIGS) => {
    for (const [id, config] of Object.entries(configs)) {
        if (!config.category || !config.name || !config.params) {
            throw new Error(`Controller '${id}' is missing required metadata.`);
        }

        for (const [paramName, schema] of Object.entries(config.params)) {
            if (!Array.isArray(schema) || schema.length !== 4) {
                throw new Error(`Controller '${id}' param '${paramName}' must be [default, min, max, step].`);
            }
        }
    }

    return true;
};
